CREATE OR REPLACE FUNCTION lab.depts_without_earner (p_min numeric)
RETURNS numeric
LANGUAGE plpgsql
SET search_path = lab, public
AS $$
DECLARE
  l_n numeric;
BEGIN
  SELECT count(*) INTO STRICT l_n
    FROM dept d
    LEFT JOIN emp e ON e.dept_id = d.dept_id
   WHERE e.salary > p_min
     AND e.emp_id IS NULL;
  RETURN l_n;
END;
$$;
